{"file_path":"main.ts","content":"// PORTFALL — hand-in program (Node 22, standard library only).
//
// The game itself is the static site under game/: plain ES modules the browser
// loads with three.js from an import map, no build step. This program hands it
// in: it copies game/ and screenshots/ from beside this file into the output
// directory and writes dossier.json there with the vendored make.fun library —
// the same library the scorer runs, so the dossier it writes here is the one
// the gate compares against.
//
// Outside the grader, MAKEFUN_OUTPUT_DIR stands in for /output:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { cpSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-threejs.ts';

const here = fileURLToPath(new URL('.', import.meta.url));
const out = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

mkdirSync(out, { recursive: true });
cpSync(join(here, 'game'), join(out, 'game'), { recursive: true });
cpSync(join(here, 'screenshots'), join(out, 'screenshots'), { recursive: true });

// The caps are the scorer's own (the kit's reference/gate.json): the text cap
// shapes the dossier's bytes, the rest make this program refuse exactly what
// the scorer would refuse — too many screenshots or one too heavy, a game/
// tree too large or too many files in it.
writeFileSync(
  join(out, 'dossier.json'),
  buildDossier(out, {
    text_max_bytes: 163840,
    screenshots: { max: 4, max_bytes: 262144 },
    game_max_files: 993,
    game_max_bytes: 50331648,
  }),
);
"}

{"file_path":"game/src/palette.js","content":"// palette.js — PORTFALL's whole look in one place: a working harbour at dusk.
// Sodium lamps and a low sun give the warm side; the sea and the cold-store
// give the cool side. Every material in the game comes from here, so the map
// reads as one chosen palette instead of a box of crayons.
import * as THREE from 'three';

export const PALETTE = {
  sky: 0x1d2733, // dusk blue over the water
  fog: 0x27333f,
  sun: 0xffb36b, // low sun, warm
  lamp: 0xffc37e,
  ground: 0x4a4d4a, // worn concrete
  groundDark: 0x3a3d3a,
  asphalt: 0x33363b, // the dock road
  linePaint: 0xd8c98a, // faded harbour paint
  rust: 0xb0562f, // Breacher rust orange
  rustDark: 0x7e3c20,
  teal: 0x2e8f83, // Warden teal
  tealDark: 0x1d5f57,
  containerRed: 0x9c4038,
  containerBlue: 0x39657e,
  containerGreen: 0x5d7350,
  containerSand: 0xa8895a,
  steel: 0x6b7178,
  steelDark: 0x454a50,
  wall: 0x8a8578, // warehouse blockwork
  wallDark: 0x655f52,
  roof: 0x3c4147,
  wood: 0x8a6b45,
  glass: 0x9fc4c9,
  bombSite: 0xe8b13c, // site paint, harbour yellow
  warden: 0x2ec4b6,
  breacher: 0xe76f51,
  skin: 0xc9a186,
  darkCloth: 0x2c2f33,
  tracer: 0xffd9a0,
  muzzle: 0xffc46b,
};

const cache = new Map();

// One MeshStandardMaterial per (colour, roughness) pair, shared by every mesh
// that wants it: the scene holds a few dozen materials, not a few thousand.
export function material(colour, roughness = 0.9, metalness = 0.0) {
  const key = `${colour}|${roughness}|${metalness}`;
  let mat = cache.get(key);
  if (!mat) {
    mat = new THREE.MeshStandardMaterial({ color: colour, roughness, metalness });
    cache.set(key, mat);
  }
  return mat;
}

export function emissiveMaterial(colour, intensity = 1.6) {
  const key = `e|${colour}|${intensity}`;
  let mat = cache.get(key);
  if (!mat) {
    mat = new THREE.MeshStandardMaterial({
      color: colour,
      emissive: colour,
      emissiveIntensity: intensity,
      roughness: 0.6,
    });
    cache.set(key, mat);
  }
  return mat;
}
"}

{"file_path":"game/src/audio.js","content":"// audio.js — every sound is synthesised with WebAudio: no audio files, nothing
// to load, and the game stays a folder of text. A noise buffer through a
// band-pass makes a gunshot; a square blip makes the charge's beeper; a sine
// drop makes the blast. The context is created lazily on the first user
// gesture, which is also what the browser's autoplay policy wants.

let ctx = null;
let master = null;
let noiseBuffer = null;

export function ensureAudio() {
  if (ctx) {
    if (ctx.state === 'suspended') ctx.resume();
    return ctx;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return null;
  ctx = new AC();
  master = ctx.createGain();
  master.gain.value = 0.5;
  master.connect(ctx.destination);
  const length = ctx.sampleRate * 1;
  noiseBuffer = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
  return ctx;
}

function noise({ at = 0, dur = 0.12, freq = 1800, q = 0.8, gain = 0.5, type = 'bandpass' }) {
  if (!ctx) return;
  const t0 = ctx.currentTime + at;
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer;
  src.loop = true;
  const filter = ctx.createBiquadFilter();
  filter.type = type;
  filter.frequency.value = freq;
  filter.Q.value = q;
  const g = ctx.createGain();
  g.gain.setValueAtTime(gain, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  src.connect(filter).connect(g).connect(master);
  src.start(t0);
  src.stop(t0 + dur + 0.02);
}

function tone({ at = 0, dur = 0.1, from = 800, to = null, gain = 0.2, type = 'square' }) {
  if (!ctx) return;
  const t0 = ctx.currentTime + at;
  const osc = ctx.createOscillator();
  osc.type = type;
  osc.frequency.setValueAtTime(from, t0);
  if (to !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(30, to), t0 + dur);
  const g = ctx.createGain();
  g.gain.setValueAtTime(gain, t0);
  g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
  osc.connect(g).connect(master);
  osc.start(t0);
  osc.stop(t0 + dur + 0.02);
}

// distance: 0 at the listener's ear, 1 at 60 metres. Far shots are a muffled
// crack, near ones are all crack and body.
export function sfxShot(kind, distance = 0) {
  if (!ctx) return;
  const near = 1 - Math.min(1, distance);
  const body = { pistol: 0.5, smg: 0.45, scatter: 0.8, carbine: 0.65, longshot: 1.0 }[kind] ?? 0.6;
  noise({ dur: 0.09 + body * 0.08, freq: 900 + near * 1600, gain: 0.12 + near * 0.4 * body });
  noise({ dur: 0.05, freq: 3200, gain: 0.1 * near });
  tone({ dur: 0.07, from: 160, to: 60, gain: 0.18 * near, type: 'triangle' });
}

export function sfxDryFire() {
  tone({ dur: 0.03, from: 1400, gain: 0.08, type: 'square' });
}

export function sfxReload() {
  tone({ dur: 0.03, from: 900, gain: 0.1 });
  tone({ at: 0.16, dur: 0.03, from: 620, gain: 0.12 });
  tone({ at: 0.34, dur: 0.04, from: 1100, gain: 0.14 });
}

export function sfxHit(kill) {
  tone({ dur: 0.05, from: kill ? 1560 : 1180, gain: 0.16, type: 'sine' });
  if (kill) tone({ at: 0.06, dur: 0.08, from: 1960, gain: 0.14, type: 'sine' });
}

export function sfxHurt() {
  noise({ dur: 0.1, freq: 500, gain: 0.25, type: 'lowpass' });
}

export function sfxBeep(final = false) {
  tone({ dur: final ? 0.3 : 0.07, from: final ? 1320 : 990, gain: 0.15, type: 'square' });
}

export function sfxExplosion() {
  if (!ctx) return;
  noise({ dur: 0.9, freq: 220, gain: 0.9, type: 'lowpass' });
  tone({ dur: 0.8, from: 120, to: 34, gain: 0.7, type: 'sine' });
}

export function sfxThrow() {
  noise({ dur: 0.08, freq: 2400, gain: 0.06 });
}

export function sfxRoundEnd(won) {
  if (!ctx) return;
  const notes = won ? [523, 659, 784] : [392, 330, 262];
  notes.forEach((f, i) => tone({ at: i * 0.13, dur: 0.22, from: f, gain: 0.12, type: 'triangle' }));
}
"}

{"file_path":"game/src/input.js","content":"// input.js — keyboard and mouse state for the player, and the pointer-lock
// handshake. The simulation reads a plain state object; nothing here knows
// about the game, and the game never touches the DOM for keys.

export function createInput(canvas, onLockChange) {
  const keys = new Set();
  const pressed = new Set(); // keys that went down since the last sim step
  let lookX = 0;
  let lookY = 0;
  let firing = false;
  let locked = false;

  window.addEventListener('keydown', (e) => {
    if (e.code === 'Tab') e.preventDefault();
    if (!keys.has(e.code)) pressed.add(e.code);
    keys.add(e.code);
  });
  window.addEventListener('keyup', (e) => keys.delete(e.code));
  window.addEventListener('blur', () => {
    keys.clear();
    firing = false;
  });

  document.addEventListener('pointerlockchange', () => {
    locked = document.pointerLockElement === canvas;
    if (!locked) firing = false;
    onLockChange(locked);
  });
  document.addEventListener('mousemove', (e) => {
    if (!locked) return;
    lookX += e.movementX || 0;
    lookY += e.movementY || 0;
  });
  canvas.addEventListener('mousedown', (e) => {
    if (locked && e.button === 0) firing = true;
  });
  window.addEventListener('mouseup', (e) => {
    if (e.button === 0) firing = false;
  });
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());

  return {
    keys,
    get locked() {
      return locked;
    },
    get firing() {
      return firing;
    },
    setFiring(v) {
      firing = v;
    },
    // Mouse travel since the last call, in pixels; the caller scales it.
    takeLook() {
      const out = { x: lookX, y: lookY };
      lookX = 0;
      lookY = 0;
      return out;
    },
    // True once per physical press of a code.
    wasPressed(code) {
      return pressed.has(code);
    },
    clearPressed() {
      pressed.clear();
    },
    requestLock() {
      canvas.requestPointerLock();
    },
  };
}
"}

{"file_path":"game/src/physics.js","content":"// physics.js — the two questions the game asks of the world: "can this body
// move here?" and "what does this ray hit first?". Bodies are upright capsules
// treated as circles on the ground plane; the map's colliders are axis-aligned
// boxes {minX, maxX, minZ, maxZ, top} where top is the box's height (a body
// standing lower than top is blocked; nothing walks on roofs here).
//
// Movement is resolved axis by axis, which gives wall sliding for free and
// never tunnels at the game's speeds and step size.

export function moveBody(body, dx, dz, colliders) {
  // body: {pos: Vector3-like {x,z}, radius}. Mutates body.pos.
  body.pos.x += dx;
  for (const c of colliders) {
    if (body.pos.y !== undefined && body.pos.y >= c.top) continue;
    resolveCircle(body.pos, body.radius, c);
  }
  body.pos.z += dz;
  for (const c of colliders) {
    if (body.pos.y !== undefined && body.pos.y >= c.top) continue;
    resolveCircle(body.pos, body.radius, c);
  }
}

function resolveCircle(pos, radius, c) {
  const nearestX = Math.max(c.minX, Math.min(pos.x, c.maxX));
  const nearestZ = Math.max(c.minZ, Math.min(pos.z, c.maxZ));
  const dx = pos.x - nearestX;
  const dz = pos.z - nearestZ;
  const d2 = dx * dx + dz * dz;
  if (d2 >= radius * radius) return;
  if (d2 > 1e-9) {
    const d = Math.sqrt(d2);
    pos.x = nearestX + (dx / d) * radius;
    pos.z = nearestZ + (dz / d) * radius;
    return;
  }
  // Centre inside the box: push out along the shallower penetration axis.
  const pushLeft = pos.x - (c.minX - radius);
  const pushRight = c.maxX + radius - pos.x;
  const pushNear = pos.z - (c.minZ - radius);
  const pushFar = c.maxZ + radius - pos.z;
  const min = Math.min(pushLeft, pushRight, pushNear, pushFar);
  if (min === pushLeft) pos.x = c.minX - radius;
  else if (min === pushRight) pos.x = c.maxX + radius;
  else if (min === pushNear) pos.z = c.minZ - radius;
  else pos.z = c.maxZ + radius;
}

// Ray vs one AABB (slab test). Returns the entry distance or Infinity.
// ro/rd are {x,y,z}; the box is {minX..maxZ, base (bottom y), top}.
export function rayBox(ro, rd, c) {
  const minY = c.base ?? 0;
  const maxY = c.top;
  let tmin = 0;
  let tmax = Infinity;
  const axes = [
    [ro.x, rd.x, c.minX, c.maxX],
    [ro.y, rd.y, minY, maxY],
    [ro.z, rd.z, c.minZ, c.maxZ],
  ];
  for (const [o, d, lo, hi] of axes) {
    if (Math.abs(d) < 1e-9) {
      if (o < lo || o > hi) return Infinity;
      continue;
    }
    let t1 = (lo - o) / d;
    let t2 = (hi - o) / d;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return Infinity;
  }
  return tmin;
}

// Ray vs a sphere; returns the entry distance or Infinity.
export function raySphere(ro, rd, centre, radius) {
  const ox = ro.x - centre.x;
  const oy = ro.y - centre.y;
  const oz = ro.z - centre.z;
  const b = ox * rd.x + oy * rd.y + oz * rd.z;
  const c = ox * ox + oy * oy + oz * oz - radius * radius;
  const disc = b * b - c;
  if (disc < 0) return Infinity;
  const t = -b - Math.sqrt(disc);
  return t > 0 ? t : Infinity;
}

// Line of sight between two points, blocked by any collider box. Used by the
// bots' eyes: cheap enough at a handful of checks per step.
export function hasLineOfSight(a, b, colliders) {
  const rd = { x: b.x - a.x, y: b.y - a.y, z: b.z - a.z };
  const dist = Math.hypot(rd.x, rd.y, rd.z);
  if (dist < 1e-6) return true;
  rd.x /= dist;
  rd.y /= dist;
  rd.z /= dist;
  for (const c of colliders) {
    const t = rayBox(a, rd, c);
    if (t < dist - 0.05) return false;
  }
  return true;
}
"}

{"file_path":"game/src/map.js","content":"// map.js — Portside Nine: a container terminal at dusk. Wardens defend from
// the west, Breachers attack from the east. Site A is the open crane pad in
// the north-west; site B is the cold-store warehouse in the south-east. Three
// lanes join the spawns — north lane, the dock road through mid, and the
// south lane — so every round is a choice about where to be outnumbered.
//
// This module builds the meshes and returns the facts the rest of the game
// runs on: AABB colliders (shared by movement and by bullet ray tests), the
// two sites, the spawns, and a waypoint graph the bots path over.
import * as THREE from 'three';
import { PALETTE, material, emissiveMaterial } from './palette.js';

const boxGeo = new THREE.BoxGeometry(1, 1, 1);

function box(scene, { w, h, d, x, y, z, colour, rough = 0.9, metal = 0, collider = true, top = null, emissive = 0 }) {
  const mesh = new THREE.Mesh(boxGeo, emissive ? emissiveMaterial(colour, emissive) : material(colour, rough, metal));
  mesh.scale.set(w, h, d);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);
  if (!collider) return mesh;
  return {
    minX: x - w / 2,
    maxX: x + w / 2,
    minZ: z - d / 2,
    maxZ: z + d / 2,
    top: top ?? y + h / 2,
  };
}

// A shipping container: a coloured box with a darker roof line and door end,
// so a stack of them reads as cargo and not as abstract blocks.
function container(scene, colliders, { x, z, along = 'x', colour, stack = false }) {
  const L = 6.06;
  const W = 2.44;
  const H = 2.6;
  const w = along === 'x' ? L : W;
  const d = along === 'x' ? W : L;
  const c = box(scene, { w, h: H, d, x, y: H / 2, z, colour, rough: 0.75, metal: 0.25 });
  colliders.push(c);
  box(scene, { w: w + 0.06, h: 0.1, d: d + 0.06, x, y: H + 0.05, z, colour: PALETTE.steelDark, collider: false });
  if (stack) {
    box(scene, { w, h: H, d, x, y: H * 1.5, z, colour, rough: 0.75, metal: 0.25, collider: false });
    box(scene, { w: w + 0.06, h: 0.1, d: d + 0.06, x, y: H * 2 + 0.05, z, colour: PALETTE.steelDark, collider: false });
    c.top = H * 2;
  }
  return c;
}

function crate(scene, colliders, { x, z, s = 1.2, colour = PALETTE.wood }) {
  const c = box(scene, { w: s, h: s, d: s, x, y: s / 2, z, colour, rough: 0.95 });
  colliders.push(c);
  return c;
}

export function createMap(scene) {
  const colliders = [];

  // --- light and air -------------------------------------------------------
  scene.background = new THREE.Color(PALETTE.sky);
  scene.fog = new THREE.Fog(PALETTE.fog, 55, 150);
  const hemi = new THREE.HemisphereLight(0x8fa3b8, 0x3a3630, 0.75);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(PALETTE.sun, 1.9);
  sun.position.set(-60, 42, -30);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -70;
  sun.shadow.camera.right = 70;
  sun.shadow.camera.top = 55;
  sun.shadow.camera.bottom = -55;
  sun.shadow.camera.far = 220;
  sun.shadow.bias = -0.0006;
  scene.add(sun);

  // --- ground --------------------------------------------------------------
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(104, 76), material(PALETTE.ground, 0.97));
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);
  const road = new THREE.Mesh(new THREE.PlaneGeometry(104, 6.4), material(PALETTE.asphalt, 0.95));
  road.rotation.x = -Math.PI / 2;
  road.position.y = 0.01;
  road.receiveShadow = true;
  scene.add(road);
  // The sea, south of the quay: a dark plane below the slab's edge.
  const sea = new THREE.Mesh(new THREE.PlaneGeometry(300, 90), material(0x1d3038, 0.35, 0.4));
  sea.rotation.x = -Math.PI / 2;
  sea.position.set(0, -0.5, 84);
  scene.add(sea);
  // Distant port silhouettes so the horizon is not empty sky.
  for (const [x, z, w, h] of [[-70, -60, 26, 17], [-30, -66, 18, 11], [24, -62, 30, 14], [72, -52, 16, 20], [80, 20, 14, 12]]) {
    box(scene, { w, h, d: 10, x, y: h / 2 - 1, z, colour: 0x232b33, collider: false });
  }

  // --- perimeter ------------------------------------------------------------
  colliders.push(box(scene, { w: 106, h: 3, d: 1, x: 0, y: 1.5, z: -37.5, colour: PALETTE.steelDark, rough: 0.8, metal: 0.3 }));
  colliders.push(box(scene, { w: 106, h: 3, d: 1, x: 0, y: 1.5, z: 37.5, colour: PALETTE.steelDark, rough: 0.8, metal: 0.3 }));
  colliders.push(box(scene, { w: 1, h: 3, d: 76, x: -51.5, y: 1.5, z: 0, colour: PALETTE.steelDark, rough: 0.8, metal: 0.3 }));
  colliders.push(box(scene, { w: 1, h: 3, d: 76, x: 51.5, y: 1.5, z: 0, colour: PALETTE.steelDark, rough: 0.8, metal: 0.3 }));

  // --- mid: the dock road choke --------------------------------------------
  container(scene, colliders, { x: -2.15, z: -6, along: 'z', colour: PALETTE.containerBlue, stack: true });
  container(scene, colliders, { x: -2.15, z: 6, along: 'z', colour: PALETTE.containerRed });
  container(scene, colliders, { x: 18, z: -5, along: 'x', colour: PALETTE.containerGreen });
  colliders.push(box(scene, { w: 3, h: 1.1, d: 1, x: 3.5, y: 0.55, z: -11.5, colour: PALETTE.groundDark, rough: 1 })); // low block, crouch cover
  colliders.push(box(scene, { w: 3, h: 1.1, d: 1, x: -10.5, y: 0.55, z: 4.5, colour: PALETTE.groundDark, rough: 1 }));

  // --- north lane ------------------------------------------------------------
  container(scene, colliders, { x: -17, z: -19.8, along: 'x', colour: PALETTE.containerSand });
  container(scene, colliders, { x: 17, z: -21.5, along: 'x', colour: PALETTE.containerRed });
  container(scene, colliders, { x: 31.2, z: -27, along: 'z', colour: PALETTE.containerBlue, stack: true });
  crate(scene, colliders, { x: 8, z: -12 });

  // --- site A: the crane pad --------------------------------------------------
  container(scene, colliders, { x: -35, z: -26.8, along: 'x', colour: PALETTE.containerGreen });
  container(scene, colliders, { x: -22.5, z: -11, along: 'z', colour: PALETTE.containerSand });
  // Gantry crane: two legs, a beam, and a container hanging over the pad.
  colliders.push(box(scene, { w: 1, h: 10, d: 1, x: -36, y: 5, z: -22, colour: PALETTE.rust, rough: 0.7, metal: 0.4 }));
  colliders.push(box(scene, { w: 1, h: 10, d: 1, x: -24, y: 5, z: -22, colour: PALETTE.rust, rough: 0.7, metal: 0.4 }));
  box(scene, { w: 15, h: 1, d: 1.4, x: -30, y: 10.2, z: -22, colour: PALETTE.rust, rough: 0.7, metal: 0.4, collider: false });
  box(scene, { w: 0.12, h: 3.4, d: 0.12, x: -31, y: 8, z: -22, colour: PALETTE.steelDark, collider: false });
  box(scene, { w: 6.06, h: 2.6, d: 2.44, x: -31, y: 4.9, z: -22, colour: PALETTE.containerBlue, rough: 0.75, metal: 0.25, collider: false });

  // --- south lane ---------------------------------------------------------------
  container(scene, colliders, { x: -21, z: 17.2, along: 'x', colour: PALETTE.containerBlue });
  container(scene, colliders, { x: 9, z: 25.2, along: 'x', colour: PALETTE.containerSand, stack: true });
  container(scene, colliders, { x: -4.8, z: 11, along: 'z', colour: PALETTE.containerGreen });
  crate(scene, colliders, { x: -8, z: 24 });
  crate(scene, colliders, { x: 24, z: -8 });

  // --- site B: the cold-store warehouse -----------------------------------------
  const wallH = 4.6;
  const wall = (opts) => colliders.push(box(scene, { ...opts, h: wallH, y: wallH / 2, colour: PALETTE.wall, rough: 0.95 }));
  wall({ w: 16.8, d: 0.4, x: 24.4, z: 9.8 }); // north wall, west of the door
  wall({ w: 8.8, d: 0.4, x: 39.6, z: 9.8 }); // north wall, east of the door
  wall({ w: 28, d: 0.4, x: 30, z: 31.8 }); // south wall
  wall({ w: 0.4, d: 4.8, x: 15.8, z: 12.4 }); // west wall, north of the door
  wall({ w: 0.4, d: 14.8, x: 15.8, z: 24.6 }); // west wall, south of the door
  wall({ w: 0.4, d: 22, x: 44.2, z: 20.8 }); // east wall
  box(scene, { w: 30, h: 0.3, d: 24, x: 30, y: wallH + 0.15, z: 20.8, colour: PALETTE.roof, rough: 0.9, collider: false }); // roof
  colliders.push(box(scene, { w: 4, h: 2.4, d: 3, x: 26, y: 1.2, z: 25.5, colour: PALETTE.glass, rough: 0.4, metal: 0.3 })); // freezer unit
  colliders.push(box(scene, { w: 2.5, h: 2.2, d: 2, x: 41.2, y: 1.1, z: 13, colour: PALETTE.steel, rough: 0.8, metal: 0.3 })); // shelving
  crate(scene, colliders, { x: 37, z: 27 });
  crate(scene, colliders, { x: 21, z: 14 });

  // Lamp posts: an emissive head and a real point light at the two sites and mid.
  for (const [x, z, withLight] of [[-30, -22, true], [30, 21, true], [0, -14, true], [10, 12, false], [-16, -2, false], [36, -8, false]]) {
    box(scene, { w: 0.18, h: 5.4, d: 0.18, x, y: 2.7, z, colour: PALETTE.steelDark, collider: false });
    box(scene, { w: 0.7, h: 0.16, d: 0.4, x, y: 5.45, z, colour: PALETTE.lamp, emissive: 2.2, collider: false });
    if (withLight) {
      const light = new THREE.PointLight(PALETTE.lamp, 60, 30, 1.8);
      light.position.set(x, 5.2, z);
      scene.add(light);
    }
  }
  // Cold-store strip lights inside the warehouse roof.
  for (const x of [22, 30, 38]) {
    box(scene, { w: 3.4, h: 0.1, d: 0.5, x, y: wallH - 0.1, z: 20.8, colour: 0xd9f2f2, emissive: 1.8, collider: false });
  }
  const storeLight = new THREE.PointLight(0xcfe8e8, 50, 26, 1.8);
  storeLight.position.set(30, 4.2, 21);
  scene.add(storeLight);

  // --- painted site rings ------------------------------------------------------
  for (const [x, z] of [[-30, -22], [30, 21]]) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(6.2, 7, 40),
      new THREE.MeshBasicMaterial({ color: PALETTE.bombSite, side: THREE.DoubleSide }),
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(x, 0.02, z);
    scene.add(ring);
  }

  // --- the facts the game runs on ------------------------------------------------
  const sites = [
    { id: 'A', name: 'Crane Pad', x: -30, z: -22, r: 7 },
    { id: 'B', name: 'Cold Store', x: 30, z: 21, r: 7 },
  ];
  const spawns = {
    warden: [[-46, -4], [-46, 0], [-46, 4], [-47.5, -2], [-47.5, 2]],
    breacher: [[46, -4], [46, 0], [46, 4], [47.5, -2], [47.5, 2]],
  };
  // Waypoints: [x, z, isCover]. Bots walk the edges; cover nodes are where a
  // bot may stop and hold an angle.
  const rawNodes = [
    [-44, 0, 0], [-38, -10, 0], [-38, 10, 0], [-34, -16, 0], [-30, -22, 1], [-24, -27, 1],
    [-12, -18, 0], [8, -18, 0], [30, -20, 0], [42, -14, 0], [40, -2, 0], [24, 0, 0],
    [4, 0, 0], [-16, 0, 0], [1.5, -6, 0], [1.5, 6, 0], [12, 14, 0], [17, 16, 0],
    [30, 21, 1], [33.5, 13, 1], [-14, 18, 0], [2, 20, 0], [-38, 22, 0], [40, 8, 0],
    [-20, -18, 0], [-30, -12, 0], [44, 0, 0],
  ];
  const rawEdges = [
    [0, 1], [0, 2], [0, 13], [1, 3], [1, 13], [2, 22], [3, 4], [3, 24], [4, 5],
    [4, 25], [5, 6], [6, 7], [6, 24], [6, 13], [7, 8], [7, 12], [8, 9], [9, 10], [9, 19],
    [10, 11], [10, 26], [11, 12], [11, 16], [11, 23], [12, 13], [12, 14], [12, 15], [12, 16],
    [13, 20], [14, 15], [16, 17], [16, 21], [17, 18], [18, 19], [20, 21],
    [20, 22], [21, 23], [23, 26], [24, 25], [3, 1],
  ];
  const nodes = rawNodes.map(([x, z, cover]) => ({ x, z, cover: cover === 1 }));
  const adjacency = nodes.map(() => []);
  for (const [a, b] of rawEdges) {
    adjacency[a].push(b);
    adjacency[b].push(a);
  }

  return { colliders, sites, spawns, nodes, adjacency };
}

// Shortest path over the waypoint graph (breadth-first; the graph is small
// and unweighted). Returns node indices from `from` to `to`, both included,
// or null when no path exists.
export function findPath(map, from, to) {
  if (from === to) return [from];
  const prev = new Array(map.nodes.length).fill(-1);
  const queue = [from];
  prev[from] = from;
  while (queue.length > 0) {
    const at = queue.shift();
    for (const next of map.adjacency[at]) {
      if (prev[next] !== -1) continue;
      prev[next] = at;
      if (next === to) {
        const path = [to];
        let cur = to;
        while (cur !== from) {
          cur = prev[cur];
          path.unshift(cur);
        }
        return path;
      }
      queue.push(next);
    }
  }
  return null;
}

export function nearestNode(map, x, z) {
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < map.nodes.length; i++) {
    const d = (map.nodes[i].x - x) ** 2 + (map.nodes[i].z - z) ** 2;
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}
"}

{"file_path":"game/src/characters.js","content":"// characters.js — the fighters' bodies: low-poly harbour operators built from
// boxes, in team colours, with a walk cycle in code. One factory makes both
// teams; the difference is cloth colour and a stripe. The same proportions
// drive the hit zones combat uses, so what you see is what you hit:
//
//   head  — a sphere at head height (the expensive place to be shot)
//   body  — the torso box (armour covers this and the head)
//   legs  — everything below the belt (cheaper damage)
import * as THREE from 'three';
import { PALETTE, material } from './palette.js';

export const HEIGHT = 1.78;
export const EYE = 1.62;

const geoCache = new Map();
function geo(w, h, d) {
  const key = `${w}|${h}|${d}`;
  let g = geoCache.get(key);
  if (!g) {
    g = new THREE.BoxGeometry(w, h, d);
    geoCache.set(key, g);
  }
  return g;
}

function part(parent, w, h, d, x, y, z, mat) {
  const mesh = new THREE.Mesh(geo(w, h, d), mat);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  parent.add(mesh);
  return mesh;
}

// Builds one fighter. Returns { group, parts, setPose } where setPose drives
// the walk/crouch/death animation from plain numbers the sim owns.
export function createCharacter(team) {
  const isWarden = team === 'warden';
  const cloth = material(isWarden ? PALETTE.teal : PALETTE.rust, 0.92);
  const clothDark = material(isWarden ? PALETTE.tealDark : PALETTE.rustDark, 0.95);
  const dark = material(PALETTE.darkCloth, 0.95);
  const skin = material(PALETTE.skin, 0.8);

  const group = new THREE.Group();
  const hips = new THREE.Group();
  hips.position.y = 0.86;
  group.add(hips);

  // Legs pivot at the hip: their geometry is translated so each box hangs
  // below its group origin, and rotation.x swings the foot.
  const legGeo = new THREE.BoxGeometry(0.17, 0.86, 0.2);
  legGeo.translate(0, -0.43, 0);
  const legL = new THREE.Mesh(legGeo, dark);
  legL.position.set(-0.11, 0, 0);
  legL.castShadow = true;
  hips.add(legL);
  const legR = new THREE.Mesh(legGeo, dark);
  legR.position.set(0.11, 0, 0);
  legR.castShadow = true;
  hips.add(legR);

  const torso = new THREE.Group();
  torso.position.y = 0.86;
  group.add(torso);
  part(torso, 0.52, 0.62, 0.28, 0, 0.31, 0, cloth); // chest
  part(torso, 0.54, 0.2, 0.3, 0, 0.5, 0, clothDark); // vest top / shoulders
  part(torso, 0.56, 0.1, 0.32, 0, 0.05, 0, dark); // belt line

  const head = new THREE.Group();
  head.position.y = 0.63; // relative to the torso group: centre lands at 1.62
  torso.add(head);
  part(head, 0.24, 0.26, 0.24, 0, 0.13, 0, skin);
  part(head, 0.27, 0.12, 0.27, 0, 0.27, 0, clothDark); // helmet / cap
  part(head, 0.27, 0.05, 0.12, 0, 0.2, -0.12, clothDark); // brim, facing -z

  const armL = new THREE.Group();
  armL.position.set(-0.33, 0.52, 0);
  torso.add(armL);
  part(armL, 0.13, 0.55, 0.15, 0, -0.24, 0, cloth);
  const armR = new THREE.Group();
  armR.position.set(0.33, 0.52, 0);
  torso.add(armR);
  part(armR, 0.13, 0.55, 0.15, 0, -0.24, 0, cloth);

  // The gun: held in the right hand, pointing where the fighter faces (-z).
  const gun = new THREE.Group();
  gun.position.set(0.1, -0.48, -0.12);
  armR.add(gun);
  part(gun, 0.07, 0.12, 0.52, 0, 0, -0.2, material(PALETTE.steelDark, 0.6, 0.5));
  part(gun, 0.05, 0.05, 0.3, 0, 0.03, -0.55, material(PALETTE.steel, 0.5, 0.6));

  let walkPhase = 0;
  let fallT = 1; // 1 = upright; death animates it to 0

  return {
    group,
    team,
    // pose: { speed (m/s), crouch 0..1, aimPitch, dead, dt }
    setPose({ speed = 0, crouch = 0, aimPitch = 0, dead = false, dt = 0 }) {
      walkPhase += dt * (2 + speed * 1.6) * (speed > 0.1 ? 1 : 0);
      const swing = Math.min(1, speed / 3) * 0.55;
      legL.rotation.x = Math.sin(walkPhase) * swing;
      legR.rotation.x = -Math.sin(walkPhase) * swing;
      armL.rotation.x = -Math.sin(walkPhase) * swing * 0.7;
      // The right arm holds the gun up at the aim pitch; the left steadies it.
      armR.rotation.x = -1.25 + aimPitch * 0.7;
      armL.rotation.x = -1.05 + aimPitch * 0.7;
      armL.position.z = -0.18;
      const drop = crouch * 0.42;
      torso.position.y = 0.86 - drop * 0.5;
      head.position.y = 0.63 - drop * 0.5;
      group.position.y = 0;
      if (dead) {
        fallT = Math.max(0, fallT - dt * 2.6);
        group.rotation.x = -(1 - fallT) * (Math.PI / 2) * 0.92;
        group.position.y = (1 - fallT) * 0.12;
      }
    },
  };
}

// Hit zones for a fighter standing at feet position `pos` with the given
// crouch amount, as plain shapes physics.js can ray-test. Head height and
// body top drop as the fighter crouches.
export function hitZones(pos, crouch) {
  const drop = crouch * 0.42;
  return {
    head: { x: pos.x, y: 1.62 - drop, z: pos.z, r: 0.19 },
    body: { minX: pos.x - 0.3, maxX: pos.x + 0.3, minZ: pos.z - 0.2, maxZ: pos.z + 0.2, base: 0.8 - drop * 0.7, top: 1.5 - drop },
    legs: { minX: pos.x - 0.28, maxX: pos.x + 0.28, minZ: pos.z - 0.18, maxZ: pos.z + 0.18, base: 0, top: 0.82 - drop * 0.7 },
  };
}
"}

{"file_path":"game/src/weapons.js","content":"// weapons.js — the armoury. Five guns and two grenades, each a row of numbers
// the combat code reads, plus the first-person view model built from boxes.
// The numbers carry the design: damage falls with range, spread is smallest
// standing still and worst in the air, and the longshot is a scalpel you must
// stop to use — accuracy counts more than speed.
import * as THREE from 'three';
import { PALETTE, material } from './palette.js';

export const WEAPONS = {
  sidearm: {
    label: 'P9 Sidearm', price: 0, damage: 26, headMult: 4, legMult: 0.75,
    rpm: 380, auto: false, mag: 12, reserve: 72, reloadMs: 1100,
    spread: { still: 0.007, move: 0.032, air: 0.09 }, recoil: 0.011,
    range: 55, pellets: 1, moveSpeed: 1.0, zoom: 1,
  },
  smg: {
    label: 'Ratter SMG', price: 1250, damage: 22, headMult: 4, legMult: 0.75,
    rpm: 750, auto: true, mag: 30, reserve: 120, reloadMs: 1900,
    spread: { still: 0.013, move: 0.046, air: 0.1 }, recoil: 0.008,
    range: 42, pellets: 1, moveSpeed: 1.0, zoom: 1,
  },
  scatter: {
    label: 'Derrick Scattergun', price: 1100, damage: 11, headMult: 2.4, legMult: 0.75,
    rpm: 68, auto: false, mag: 6, reserve: 30, reloadMs: 2600,
    spread: { still: 0.045, move: 0.06, air: 0.11 }, recoil: 0.05,
    range: 20, pellets: 8, moveSpeed: 0.97, zoom: 1,
  },
  carbine: {
    label: 'Harbor Carbine', price: 2700, damage: 34, headMult: 4, legMult: 0.75,
    rpm: 600, auto: true, mag: 30, reserve: 120, reloadMs: 2100,
    spread: { still: 0.004, move: 0.034, air: 0.1 }, recoil: 0.013,
    range: 80, pellets: 1, moveSpeed: 0.95, zoom: 1,
  },
  longshot: {
    label: 'Gullwing Longshot', price: 4750, damage: 96, headMult: 2.6, legMult: 0.6,
    rpm: 42, auto: false, mag: 5, reserve: 25, reloadMs: 2900,
    spread: { still: 0.0008, move: 0.11, air: 0.16 }, recoil: 0.055,
    range: 140, pellets: 1, moveSpeed: 0.92, zoom: 3.2,
  },
};

export const GRENADES = {
  frag: { label: 'Frag Grenade', price: 300, fuseMs: 1600, radius: 5.5, damage: 92 },
  flash: { label: 'Flash Charge', price: 200, fuseMs: 1200, radius: 19, damage: 0 },
};

export const ARMOR_PRICE = 650;
export const ARMOR_HELMET_PRICE = 1000;

// A fresh carried weapon: what a fighter holds, as opposed to its table row.
export function makeWeapon(kind) {
  const def = WEAPONS[kind];
  return {
    kind,
    def,
    mag: def.mag,
    reserve: def.reserve,
    reloadingUntil: 0,
    nextShotAt: 0,
    burst: 0, // shots since the trigger was last released: drives recoil climb
  };
}

// Spread in radians for a shot, from how the shooter is moving. `airborne`
// dominates: a jumping shot is a prayer.
export function spreadFor(def, speed, airborne) {
  if (airborne) return def.spread.air;
  const t = Math.min(1, speed / 4.6);
  return def.spread.still + (def.spread.move - def.spread.still) * t;
}

// Damage after range falloff: full inside a third of the range, then a
// straight slide to 55% at the full range and beyond.
export function damageAt(def, dist) {
  const t = Math.max(0, Math.min(1, (dist - def.range / 3) / (def.range * 2 / 3)));
  return def.damage * (1 - 0.45 * t);
}

// --- view models ------------------------------------------------------------
// One group per gun kind, built once and swapped visible. The muzzle marker
// is where flashes and tracers start.

const darkMetal = () => material(PALETTE.steelDark, 0.55, 0.55);
const midMetal = () => material(PALETTE.steel, 0.45, 0.6);

function box(parent, w, h, d, x, y, z, mat) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  mesh.position.set(x, y, z);
  parent.add(mesh);
  return mesh;
}

export function createViewModel(kind) {
  const g = new THREE.Group();
  const muzzle = new THREE.Object3D();
  if (kind === 'sidearm') {
    box(g, 0.055, 0.09, 0.21, 0, 0, -0.08, darkMetal());
    box(g, 0.05, 0.12, 0.06, 0, -0.09, 0.03, midMetal());
    muzzle.position.set(0, 0.02, -0.2);
  } else if (kind === 'smg') {
    box(g, 0.06, 0.1, 0.34, 0, 0, -0.1, darkMetal());
    box(g, 0.045, 0.045, 0.2, 0, 0.01, -0.34, midMetal());
    box(g, 0.045, 0.16, 0.05, 0, -0.12, -0.02, darkMetal());
    box(g, 0.05, 0.07, 0.12, 0, 0.09, 0.02, midMetal());
    muzzle.position.set(0, 0.01, -0.46);
  } else if (kind === 'scatter') {
    box(g, 0.07, 0.09, 0.5, 0, 0, -0.16, material(PALETTE.wood, 0.8));
    box(g, 0.055, 0.055, 0.34, 0, 0.03, -0.4, darkMetal());
    box(g, 0.06, 0.08, 0.16, 0, -0.05, 0.08, material(PALETTE.wood, 0.8));
    muzzle.position.set(0, 0.03, -0.58);
  } else if (kind === 'longshot') {
    box(g, 0.06, 0.09, 0.62, 0, -0.01, -0.2, material(PALETTE.tealDark, 0.6, 0.2));
    box(g, 0.04, 0.04, 0.42, 0, 0.02, -0.62, darkMetal());
    box(g, 0.05, 0.09, 0.16, 0, 0.1, -0.16, darkMetal()); // scope
    box(g, 0.045, 0.14, 0.05, 0, -0.11, 0.02, darkMetal());
    muzzle.position.set(0, 0.02, -0.84);
  } else {
    // carbine
    box(g, 0.065, 0.11, 0.46, 0, 0, -0.14, darkMetal());
    box(g, 0.05, 0.05, 0.26, 0, 0.02, -0.46, midMetal());
    box(g, 0.05, 0.17, 0.06, 0, -0.13, -0.06, darkMetal());
    box(g, 0.055, 0.06, 0.14, 0, 0.1, -0.05, midMetal()); // carry sight
    box(g, 0.05, 0.09, 0.12, 0, -0.03, 0.14, material(PALETTE.darkCloth, 0.9)); // stock
    muzzle.position.set(0, 0.02, -0.6);
  }
  g.add(muzzle);
  g.userData.muzzle = muzzle;
  return g;
}
"}

{"file_path":"game/src/effects.js","content":"// effects.js — the short-lived visuals: tracers, muzzle flashes, impact
// sparks, grenade arcs and the charge itself. Everything is pooled and
// reused; an effect is a few meshes whose life is counted in frames, and the
// update loop walks a fixed-size ring instead of allocating per shot.
import * as THREE from 'three';
import { PALETTE, emissiveMaterial, material } from './palette.js';

const MAX_TRACERS = 48;
const MAX_SPARKS = 40;

export function createEffects(scene) {
  // --- tracers: one stretched additive quad per shot, gone in 60 ms --------
  const tracerGeo = new THREE.BoxGeometry(0.02, 0.02, 1);
  const tracerMat = new THREE.MeshBasicMaterial({ color: PALETTE.tracer, transparent: true, opacity: 0.85 });
  const tracers = [];
  for (let i = 0; i < MAX_TRACERS; i++) {
    const mesh = new THREE.Mesh(tracerGeo, tracerMat);
    mesh.visible = false;
    scene.add(mesh);
    tracers.push({ mesh, life: 0 });
  }
  let tracerAt = 0;

  // --- sparks: a small bright octahedron that pops and shrinks -------------
  const sparkGeo = new THREE.OctahedronGeometry(0.09);
  const sparks = [];
  for (let i = 0; i < MAX_SPARKS; i++) {
    const mesh = new THREE.Mesh(sparkGeo, new THREE.MeshBasicMaterial({ color: 0xffe2b0, transparent: true }));
    mesh.visible = false;
    scene.add(mesh);
    sparks.push({ mesh, life: 0, max: 1 });
  }
  let sparkAt = 0;

  // --- one shared muzzle light and flash plane ------------------------------
  const flashLight = new THREE.PointLight(PALETTE.muzzle, 0, 9, 2);
  scene.add(flashLight);
  const flashPlane = new THREE.Mesh(
    new THREE.PlaneGeometry(0.26, 0.26),
    new THREE.MeshBasicMaterial({ color: 0xffd9a0, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false }),
  );
  flashPlane.visible = false;
  scene.add(flashPlane);
  let flashLife = 0;

  // --- explosion / flashbang bloom -------------------------------------------
  const bloom = new THREE.Mesh(
    new THREE.SphereGeometry(1, 20, 14),
    new THREE.MeshBasicMaterial({ color: 0xffb36b, transparent: true, opacity: 0 }),
  );
  bloom.visible = false;
  scene.add(bloom);
  const bloomLight = new THREE.PointLight(0xffc37e, 0, 26, 1.6);
  scene.add(bloomLight);
  let bloomT = 1; // 1 = idle
  let bloomKind = 'frag';

  const from = new THREE.Vector3();
  const to = new THREE.Vector3();
  const mid = new THREE.Vector3();

  return {
    tracer(a, b) {
      const t = tracers[tracerAt];
      tracerAt = (tracerAt + 1) % MAX_TRACERS;
      from.copy(a);
      to.copy(b);
      const len = from.distanceTo(to);
      if (len < 0.5) return;
      mid.addVectors(from, to).multiplyScalar(0.5);
      t.mesh.position.copy(mid);
      t.mesh.scale.set(1, 1, len);
      t.mesh.lookAt(to);
      t.mesh.visible = true;
      t.life = 0.06;
    },
    spark(point, colour = 0xffe2b0, life = 0.16, scale = 1) {
      const s = sparks[sparkAt];
      sparkAt = (sparkAt + 1) % MAX_SPARKS;
      s.mesh.position.copy(point);
      s.mesh.material.color.setHex(colour);
      s.mesh.scale.setScalar(scale);
      s.mesh.visible = true;
      s.life = life;
      s.max = life;
    },
    muzzle(point, cameraDir) {
      flashLight.position.copy(point);
      flashLight.intensity = 26;
      flashPlane.position.copy(point);
      if (cameraDir) flashPlane.lookAt(point.x + cameraDir.x, point.y + cameraDir.y, point.z + cameraDir.z);
      flashPlane.visible = true;
      flashPlane.material.opacity = 0.9;
      flashPlane.rotation.z = Math.random() * Math.PI;
      flashLife = 0.045;
    },
    explode(point, kind) {
      bloom.position.copy(point);
      bloom.material.color.setHex(kind === 'flash' ? 0xffffff : 0xffb36b);
      bloom.visible = true;
      bloomT = 0;
      bloomKind = kind;
      bloomLight.position.copy(point).y += 1;
      bloomLight.intensity = kind === 'flash' ? 60 : 120;
    },
    update(dt) {
      for (const t of tracers) {
        if (t.life <= 0) continue;
        t.life -= dt;
        if (t.life <= 0) t.mesh.visible = false;
      }
      for (const s of sparks) {
        if (s.life <= 0) continue;
        s.life -= dt;
        const k = Math.max(0, s.life / s.max);
        s.mesh.material.opacity = k;
        s.mesh.scale.multiplyScalar(1 - dt * 2.2);
        if (s.life <= 0) s.mesh.visible = false;
      }
      if (flashLife > 0) {
        flashLife -= dt;
        if (flashLife <= 0) {
          flashLight.intensity = 0;
          flashPlane.visible = false;
        }
      }
      if (bloomT < 1) {
        bloomT = Math.min(1, bloomT + dt * (bloomKind === 'flash' ? 1.4 : 2.2));
        const r = bloomKind === 'flash' ? 2.2 : 0.6 + bloomT * 4.6;
        bloom.scale.setScalar(r);
        bloom.material.opacity = 0.75 * (1 - bloomT);
        bloomLight.intensity *= Math.max(0, 1 - dt * 7);
        if (bloomT >= 1) bloom.visible = false;
      }
    },
  };
}

// The breach charge: a slab with a keypad and a light that blinks faster the
// closer it gets to going off. Carried, dropped and planted states all use
// this one mesh; the game moves it.
export function createBomb() {
  const group = new THREE.Group();
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.16, 0.32), material(PALETTE.steelDark, 0.6, 0.4));
  body.position.y = 0.08;
  body.castShadow = true;
  group.add(body);
  const pad = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.04, 0.16), emissiveMaterial(0x39d353, 0.9));
  pad.position.set(0, 0.17, 0);
  group.add(pad);
  const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.035, 10, 8), emissiveMaterial(0xff4444, 2.4));
  lamp.position.set(0.15, 0.18, 0.08);
  group.add(lamp);
  return {
    group, lamp, pad,
    // Blink the warning lamp at the given rate (Hz); 0 = steady on.
    setLamp(hz) {
      lamp.visible = hz <= 0 ? true : (performance.now() / 1000 * hz) % 1 < 0.55;
    },
  };
}
"}

{"file_path":"game/src/hud.js","content":"// hud.js — everything drawn over the canvas: vitals, ammunition, money, the
// round clock, the score, the killfeed, banners, the buy menu, the channel
// bar for planting and defusing, and the scoreboard. It owns the DOM nodes
// index.html declares and nothing else; the game pushes numbers in.
import { WEAPONS, GRENADES } from './weapons.js';

const $ = (id) => document.getElementById(id);

export function createHud() {
  const els = {
    health: $('health-num'),
    armor: $('armor-num'),
    money: $('money-num'),
    ammoMag: $('ammo-mag'),
    ammoReserve: $('ammo-reserve'),
    weaponName: $('weapon-name'),
    grenades: $('grenade-count'),
    timer: $('timer'),
    phase: $('phase-label'),
    scoreW: $('score-w'),
    scoreB: $('score-b'),
    killfeed: $('killfeed'),
    banner: $('banner'),
    bannerTitle: $('banner-title'),
    bannerSub: $('banner-sub'),
    hitmarker: $('hitmarker'),
    crosshair: $('crosshair'),
    damage: $('damage'),
    flash: $('flash'),
    channelWrap: $('channel-wrap'),
    channelFill: $('channel-fill'),
    channelLabel: $('channel-label'),
    bombStatus: $('bomb-status'),
    buyMenu: $('buy-menu'),
    buyItems: $('buy-items'),
    buyMoney: $('buy-money'),
    scoreboard: $('scoreboard'),
    scoreRows: $('score-rows'),
    overlay: $('overlay'),
    overlayTitle: $('overlay-title'),
    overlayCopy: $('overlay-copy'),
    playBtn: $('play-btn'),
    scope: $('scope'),
  };

  let bannerTimer = 0;

  function esc(s) {
    return String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  }

  return {
    els,
    setHealth(v) {
      els.health.textContent = Math.max(0, Math.ceil(v));
      els.health.classList.toggle('low', v <= 30);
    },
    setArmor(v) {
      els.armor.textContent = Math.max(0, Math.ceil(v));
    },
    setMoney(v) {
      els.money.textContent = `$${v}`;
    },
    setAmmo(mag, reserve, reloading) {
      els.ammoMag.textContent = reloading ? '--' : mag;
      els.ammoReserve.textContent = `/ ${reserve}`;
      els.ammoMag.classList.toggle('low', !reloading && mag <= 5);
    },
    setWeapon(label) {
      els.weaponName.textContent = label;
    },
    setGrenades(frag, flash) {
      els.grenades.textContent = `FRAG ${frag} · FLASH ${flash}`;
    },
    setTimer(text, urgent) {
      els.timer.textContent = text;
      els.timer.classList.toggle('urgent', !!urgent);
    },
    setPhase(text) {
      els.phase.textContent = text;
    },
    setScores(w, b) {
      els.scoreW.textContent = w;
      els.scoreB.textContent = b;
    },
    setBombStatus(text) {
      els.bombStatus.textContent = text;
      els.bombStatus.style.display = text ? 'block' : 'none';
    },
    banner(title, sub = '', holdMs = 2600) {
      els.bannerTitle.textContent = title;
      els.bannerSub.textContent = sub;
      els.banner.classList.add('show');
      window.clearTimeout(bannerTimer);
      bannerTimer = window.setTimeout(() => els.banner.classList.remove('show'), holdMs);
    },
    killfeed(killerName, killerTeam, victimName, victimTeam, weaponLabel, headshot) {
      const row = document.createElement('div');
      row.className = 'kf-row';
      row.innerHTML =
        `<span class="${killerTeam}">${esc(killerName)}</span>` +
        `<em>${esc(weaponLabel)}${headshot ? ' ⌖' : ''}</em>` +
        `<span class="${victimTeam}">${esc(victimName)}</span>`;
      els.killfeed.appendChild(row);
      while (els.killfeed.children.length > 5) els.killfeed.firstChild.remove();
      window.setTimeout(() => row.classList.add('fade'), 4200);
      window.setTimeout(() => row.remove(), 5000);
    },
    hitmarker(kill) {
      els.hitmarker.classList.toggle('kill', !!kill);
      els.hitmarker.classList.add('on');
      window.setTimeout(() => els.hitmarker.classList.remove('on'), kill ? 220 : 110);
    },
    damageFlash() {
      els.damage.classList.add('on');
      window.setTimeout(() => els.damage.classList.remove('on'), 130);
    },
    setFlash(v) {
      els.flash.style.opacity = String(Math.max(0, Math.min(1, v)));
    },
    setCrosshairSpread(px) {
      els.crosshair.style.setProperty('--sp', `${Math.round(px)}px`);
    },
    setScope(on) {
      els.scope.style.display = on ? 'block' : 'none';
      els.crosshair.style.opacity = on ? '0' : '1';
    },
    channel(label, frac) {
      if (frac === null) {
        els.channelWrap.style.display = 'none';
        return;
      }
      els.channelWrap.style.display = 'block';
      els.channelLabel.textContent = label;
      els.channelFill.style.width = `${Math.round(frac * 100)}%`;
    },
    // items: [{key, label, price, note, canBuy, owned}]
    renderBuy(money, items, open) {
      els.buyMenu.style.display = open ? 'block' : 'none';
      if (!open) return;
      els.buyMoney.textContent = `$${money}`;
      els.buyItems.innerHTML = items
        .map(
          (it, i) =>
            `<div class="buy-item ${it.canBuy ? '' : 'cant'} ${it.owned ? 'owned' : ''}">` +
            `<span class="buy-key">${i + 1}</span>` +
            `<span class="buy-label">${esc(it.label)}</span>` +
            `<span class="buy-note">${esc(it.note ?? '')}</span>` +
            `<span class="buy-price">${it.owned ? 'OWNED' : `$${it.price}`}</span></div>`,
        )
        .join('');
    },
    scoreboard(rows) {
      if (!rows) {
        els.scoreboard.style.display = 'none';
        return;
      }
      els.scoreboard.style.display = 'block';
      els.scoreRows.innerHTML = rows
        .map(
          (r) =>
            `<div class="sb-row ${r.team}"><span>${esc(r.name)}</span><span>${r.kills}</span><span>${r.deaths}</span><span>$${r.money}</span></div>`,
        )
        .join('');
    },
    showOverlay(title, copy, button) {
      els.overlayTitle.textContent = title;
      els.overlayCopy.innerHTML = copy;
      els.playBtn.textContent = button;
      els.overlay.style.display = 'grid';
    },
    hideOverlay() {
      els.overlay.style.display = 'none';
    },
    onPlay(fn) {
      els.playBtn.addEventListener('click', fn);
    },
  };
}

export function weaponLabel(kind) {
  return WEAPONS[kind]?.label ?? kind;
}
export function grenadeLabel(kind) {
  return GRENADES[kind]?.label ?? kind;
}
"}

{"file_path":"game/src/bots.js","content":"// bots.js — the nine fighters nobody is holding a mouse for. Each bot runs
// the same loop a player would: look, remember, decide, move. Perception is
// honest — a bot knows an enemy's position only if it has seen them (vision
// cone and line of sight) or heard them (gunfire, running feet) — and its aim
// is a human-ish error that settles the longer it tracks a target and the
// stiller it stands.
//
// The brain writes intents onto its fighter (moveVec, moveSpeed, aimYaw,
// aimPitch, triggerHeld, channel); main.js executes them with the same code
// the player's body and gun use, so a bot's bullets obey the same rules.
import { hasLineOfSight } from './physics.js';
import { findPath, nearestNode } from './map.js';

const SIGHT_RANGE = 58;
const FOV_COS = Math.cos(1.45); // ~83 degrees each way
const HEAR_SHOTS = 34;
const HEAR_STEPS = 9;

export function createBot(fighter, map, rng) {
  const brain = {
    fighter,
    path: [],
    pathI: 0,
    goalNode: -1,
    memory: new Map(), // fighter -> {x, z, t}
    target: null,
    targetSince: 0,
    lastSawTargetAt: -9,
    thinkAt: rng() * 0.12,
    repathAt: 0,
    burstUntil: 0,
    pauseUntil: 0,
    reactionUntil: 0,
    state: 'advance',
    holdYaw: fighter.yaw,
    seed: rng(),
  };

  function eyePos(f) {
    return { x: f.body.pos.x, y: 1.52, z: f.body.pos.z };
  }

  function perceive(now, ctx) {
    const me = fighter;
    const seen = [];
    for (const other of ctx.fighters) {
      if (!other.alive || other.team === me.team) continue;
      const dx = other.body.pos.x - me.body.pos.x;
      const dz = other.body.pos.z - me.body.pos.z;
      const dist = Math.hypot(dx, dz);
      let sensed = false;
      if (dist < SIGHT_RANGE) {
        const fx = -Math.sin(me.yaw);
        const fz = -Math.cos(me.yaw);
        const dot = dist > 0.01 ? (dx * fx + dz * fz) / dist : 1;
        if (dot > FOV_COS || dist < 6.5) {
          const chest = { x: other.body.pos.x, y: 1.22, z: other.body.pos.z };
          if (hasLineOfSight(eyePos(me), chest, ctx.colliders)) sensed = true;
        }
        if (!sensed && other.speedNow > 4 && dist < HEAR_STEPS) sensed = true;
      }
      if (sensed) {
        brain.memory.set(other, { x: other.body.pos.x, z: other.body.pos.z, t: now });
        seen.push(other);
      }
    }
    // Gunfire is information: remember where the last enemy shot came from.
    for (const n of ctx.noise) {
      if (n.team === me.team || now - n.t > 0.3) continue;
      const d = Math.hypot(n.x - me.body.pos.x, n.z - me.body.pos.z);
      if (d < HEAR_SHOTS) {
        // Attribute the noise to the nearest living enemy, approximately.
        let best = null;
        let bestD = Infinity;
        for (const other of ctx.fighters) {
          if (!other.alive || other.team === me.team) continue;
          const dd = Math.hypot(other.body.pos.x - n.x, other.body.pos.z - n.z);
          if (dd < bestD) {
            bestD = dd;
            best = other;
          }
        }
        if (best) brain.memory.set(best, { x: n.x, z: n.z, t: n.t });
      }
    }
    // Pick the freshest, closest remembered enemy as the target.
    let bestTarget = null;
    let bestScore = -Infinity;
    for (const [other, mem] of brain.memory) {
      if (!other.alive) continue;
      const age = now - mem.t;
      if (age > 4) continue;
      const d = Math.hypot(mem.x - me.body.pos.x, mem.z - me.body.pos.z);
      const score = (seen.includes(other) ? 100 : 0) - d - age * 6;
      if (score > bestScore) {
        bestScore = score;
        bestTarget = other;
      }
    }
    if (bestTarget !== brain.target) {
      brain.target = bestTarget;
      brain.targetSince = now;
      brain.reactionUntil = now + 0.26 + brain.seed * 0.24;
    }
    if (bestTarget && seen.includes(bestTarget)) brain.lastSawTargetAt = now;
    return seen;
  }

  function setGoal(nodeIdx, now) {
    if (nodeIdx === brain.goalNode && brain.path.length > 0) return;
    brain.goalNode = nodeIdx;
    const from = nearestNode(map, fighter.body.pos.x, fighter.body.pos.z);
    brain.path = findPath(map, from, nodeIdx) ?? [nodeIdx];
    brain.pathI = brain.path.length > 1 ? 1 : 0;
    brain.repathAt = now + 0.7;
  }

  // Walk the path; returns true when the final node is reached.
  function followPath(dt, speed) {
    const me = fighter;
    if (brain.pathI >= brain.path.length) return true;
    const node = map.nodes[brain.path[brain.pathI]];
    const dx = node.x - me.body.pos.x;
    const dz = node.z - me.body.pos.z;
    const dist = Math.hypot(dx, dz);
    if (dist < 0.7) {
      brain.pathI += 1;
      return brain.pathI >= brain.path.length;
    }
    me.moveVec.x = dx / dist;
    me.moveVec.z = dz / dist;
    me.moveSpeed = speed;
    me.aimYaw = Math.atan2(-me.moveVec.x, -me.moveVec.z);
    return false;
  }

  function faceToward(x, z) {
    const me = fighter;
    me.aimYaw = Math.atan2(-(x - me.body.pos.x), -(z - me.body.pos.z));
  }

  function step(dt, now, ctx) {
    const me = fighter;
    me.moveVec.x = 0;
    me.moveVec.z = 0;
    me.moveSpeed = 0;
    me.triggerHeld = false;
    me.channel = null;
    me.crouchWanted = false;
    if (!me.alive) return;

    if (now >= brain.thinkAt) {
      brain.thinkAt = now + 0.12;
      perceive(now, ctx);
    }

    const plan = me.plan;
    const bomb = ctx.bomb;
    const targetMem = brain.target ? brain.memory.get(brain.target) : null;
    const targetFresh = targetMem && now - targetMem.t < 2.2;
    const targetVisible = brain.target && brain.target.alive && now - brain.lastSawTargetAt < 0.25;

    // --- channel work first: planting and defusing are commitments --------
    if (me.team === 'breacher' && bomb.state === 'carried' && bomb.carrier === me) {
      const site = ctx.sites[plan.site === 'B' ? 1 : 0];
      const d = Math.hypot(me.body.pos.x - site.x, me.body.pos.z - site.z);
      if (d < site.r - 1.6) {
        me.channel = 'plant';
        me.crouchWanted = true;
        faceToward(me.body.pos.x - 6, site.z); // watch back toward the Warden half
        return;
      }
    }
    if (me.team === 'warden' && bomb.state === 'planted' && plan.defuser) {
      const d = Math.hypot(me.body.pos.x - bomb.x, me.body.pos.z - bomb.z);
      if (d < 2.1) {
        me.channel = 'defuse';
        me.crouchWanted = true;
        faceToward(bomb.x, bomb.z);
        if (!targetVisible) return;
      }
    }

    // --- combat: a fresh target interrupts everything but a channel -------
    if (targetFresh && brain.target) {
      const t = brain.target;
      const mem = targetMem;
      const dx = mem.x - me.body.pos.x;
      const dz = mem.z - me.body.pos.z;
      const dist = Math.hypot(dx, dz);
      faceToward(mem.x, mem.z);
      me.aimTargetPos = { x: mem.x, y: me.weaponKind === 'longshot' ? 1.42 : 1.24, z: mem.z };
      const trackTime = now - brain.targetSince;
      me.aimError = Math.max(0.011, 0.055 - trackTime * 0.05);
      if (targetVisible && now >= brain.reactionUntil) {
        if (now >= brain.pauseUntil && now >= brain.burstUntil) {
          const burstLen = me.weaponKind === 'sidearm' || me.weaponKind === 'longshot' ? 0.12 : 0.3 + brain.seed * 0.3;
          brain.burstUntil = now + burstLen;
          brain.pauseUntil = brain.burstUntil + 0.28 + brain.seed * 0.4;
        }
        me.triggerHeld = now < brain.burstUntil;
      }
      if (dist > 15) {
        // Close the distance, firing on the move and paying for it in spread.
        me.moveVec.x = dx / dist;
        me.moveVec.z = dz / dist;
        me.moveSpeed = 3.4;
      } else if (dist < 5 && me.hp < 35) {
        me.moveVec.x = -dx / dist;
        me.moveVec.z = -dz / dist;
        me.moveSpeed = 3.2;
      } else {
        // In range: stop, sometimes crouch, and let the spread settle.
        me.moveSpeed = 0;
        me.crouchWanted = brain.seed > 0.55;
        // Small strafe between bursts to stay a harder target.
        if (!me.triggerHeld && now > brain.pauseUntil - 0.2) {
          const s = brain.seed > 0.5 ? 1 : -1;
          me.moveVec.x = -dz / dist * s;
          me.moveVec.z = dx / dist * s;
          me.moveSpeed = 1.6;
        }
      }
      return;
    }

    // --- objectives ---------------------------------------------------------
    if (bomb.state === 'planted') {
      const siteIdx = bomb.site === 'B' ? 1 : 0;
      if (me.team === 'warden') {
        setGoal(nearestNode(map, bomb.x, bomb.z), now);
        followPath(dt, 4.7);
      } else {
        // Breachers hold the site they planted on.
        const site = ctx.sites[siteIdx];
        const cover = nearestCoverNear(site.x, site.z);
        setGoal(cover, now);
        if (followPath(dt, 4.4)) holdAngle(ctx);
      }
      return;
    }
    if (bomb.state === 'dropped' && me.team === 'breacher') {
      setGoal(nearestNode(map, bomb.x, bomb.z), now);
      followPath(dt, 4.7);
      return;
    }

    if (plan.role === 'planter' || plan.role === 'escort') {
      const site = ctx.sites[plan.site === 'B' ? 1 : 0];
      setGoal(nearestNode(map, site.x, site.z), now);
      if (followPath(dt, plan.role === 'planter' ? 4.7 : 4.4)) holdAngle(ctx);
      return;
    }
    // Warden holders: get to the assigned cover node and watch the lane.
    setGoal(plan.holdNode, now);
    if (followPath(dt, 4.5)) holdAngle(ctx);
  }

  function nearestCoverNear(x, z) {
    let best = 0;
    let bestD = Infinity;
    for (let i = 0; i < map.nodes.length; i++) {
      if (!map.nodes[i].cover) continue;
      const d = (map.nodes[i].x - x) ** 2 + (map.nodes[i].z - z) ** 2;
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  function holdAngle(ctx) {
    const me = fighter;
    me.moveSpeed = 0;
    me.crouchWanted = brain.seed > 0.4;
    // Watch toward the enemy's half of the map: Wardens look east, Breachers west.
    faceToward(me.team === 'warden' ? 46 : -46, me.body.pos.z * 0.4);
  }

  return { step, brain };
}
"}

{"file_path":"game/src/player.js","content":"// player.js — the local player's body: mouse look with recoil, and ground
// movement with acceleration and friction in the Counter-Strike shape —
// you are fast or you are accurate, never both, because spread reads the
// same speed this module reports. Crouching is slower and lower; walking
// (Shift) is slower still and silent, which the bots' ears respect.
import { moveBody } from './physics.js';

export const RUN_SPEED = 5.2;
export const WALK_SPEED = 2.7;
export const CROUCH_SPEED = 1.9;
export const EYE_STAND = 1.62;
export const EYE_CROUCH = 1.18;

const ACCEL = 42;
const FRICTION = 9.5;
const GRAVITY = 14.5;
const JUMP_VEL = 4.9;

export function createPlayer(colliders) {
  const body = {
    pos: { x: -46, y: 0, z: 0 },
    radius: 0.38,
  };
  const state = {
    body,
    vel: { x: 0, z: 0 },
    vy: 0,
    yaw: -Math.PI / 2, // facing +x, from the Warden spawn toward mid
    pitch: 0,
    recoilPitch: 0,
    recoilYaw: 0,
    crouch: 0, // 0 standing, 1 fully crouched (eased)
    crouching: false,
    walking: false,
    airborne: false,
    speed: 0,
  };

  function look(dx, dy) {
    state.yaw -= dx * 0.0021;
    state.pitch -= dy * 0.0021;
    const lim = 1.45;
    state.pitch = Math.max(-lim, Math.min(lim, state.pitch));
  }

  function addRecoil(pitchKick, yawKick) {
    state.recoilPitch += pitchKick;
    state.recoilYaw += yawKick;
  }

  // keys: the input module's Set of codes. dt: fixed step.
  function step(dt, keys) {
    const wantCrouch = keys.has('ControlLeft') || keys.has('ControlRight') || keys.has('KeyC');
    state.crouching = wantCrouch;
    state.crouch += ((wantCrouch ? 1 : 0) - state.crouch) * Math.min(1, dt * 11);
    state.walking = keys.has('ShiftLeft') || keys.has('ShiftRight');

    const sin = Math.sin(state.yaw);
    const cos = Math.cos(state.yaw);
    let ix = 0;
    let iz = 0;
    if (keys.has('KeyW')) iz -= 1;
    if (keys.has('KeyS')) iz += 1;
    if (keys.has('KeyA')) ix -= 1;
    if (keys.has('KeyD')) ix += 1;
    // Camera forward on the ground plane is (-sin(yaw), -cos(yaw)) for the
    // three.js YXZ convention this game uses.
    const wishX = -sin * -iz + -cos * ix * -1;
    const wishZ = -cos * -iz + sin * ix * -1;
    const wishLen = Math.hypot(wishX, wishZ);
    const maxSpeed = state.crouching ? CROUCH_SPEED : state.walking ? WALK_SPEED : RUN_SPEED;

    if (wishLen > 0.01) {
      const nx = wishX / wishLen;
      const nz = wishZ / wishLen;
      state.vel.x += nx * ACCEL * dt;
      state.vel.z += nz * ACCEL * dt;
      const sp = Math.hypot(state.vel.x, state.vel.z);
      if (sp > maxSpeed) {
        state.vel.x *= maxSpeed / sp;
        state.vel.z *= maxSpeed / sp;
      }
    } else {
      const drop = Math.max(0, 1 - FRICTION * dt);
      state.vel.x *= drop;
      state.vel.z *= drop;
      if (Math.hypot(state.vel.x, state.vel.z) < 0.02) {
        state.vel.x = 0;
        state.vel.z = 0;
      }
    }

    if (keys.has('Space') && !state.airborne) {
      state.vy = JUMP_VEL;
      state.airborne = true;
    }
    if (state.airborne) {
      state.vy -= GRAVITY * dt;
      body.pos.y += state.vy * dt;
      if (body.pos.y <= 0) {
        body.pos.y = 0;
        state.vy = 0;
        state.airborne = false;
      }
    }

    moveBody(body, state.vel.x * dt, state.vel.z * dt, colliders);
    // The yard is fenced; keep the body inside it whatever happens.
    body.pos.x = Math.max(-50.6, Math.min(50.6, body.pos.x));
    body.pos.z = Math.max(-36.6, Math.min(36.6, body.pos.z));
    state.speed = Math.hypot(state.vel.x, state.vel.z);

    // Recoil is a spring: it kicks the view up and settles back, so a burst
    // climbs and a paused trigger recovers your aim.
    state.recoilPitch *= Math.max(0, 1 - dt * 7.5);
