  const wardens = fighters.filter((f) => f.team === 'warden' && !f.isPlayer);
  const site = match.round % 2 === 1 ? (rng() < 0.5 ? 'A' : 'B') : rng() < 0.5 ? 'B' : 'A';
  const planter = breachers[Math.floor(rng() * breachers.length)];
