        w.reserve = w.def.reserve;
        w.reloadingUntil = 0;
      }
    }
    if (f.char) {
      f.char.group.visible = true;
      f.char.group.rotation.set(0, 0, 0);
    }
  }
  player.teleport(playerFighter.body.pos.x, playerFighter.body.pos.z, -Math.PI / 2);
  bombProp.group.visible = true;
