}

function startMatch() {
  match.scoreW = 0;
  match.scoreB = 0;
  match.round = 0;
  for (const f of fighters) {
    f.money = START_MONEY;
    f.kills = 0;
    f.deaths = 0;
    f.weapons.primary = null;
    f.weaponKind = 'sidearm';
    f.weapons.sidearm = makeWeapon('sidearm');
    f.armor = 0;
    f.helmet = false;
    f.grenades = { frag: 0, flash: 0 };
    f.diedLastRound = false;
  }
