  #hitmarker i:nth-child(2) { left: 11px; bottom: 0; width: 2px; height: 7px; }
  #hitmarker i:nth-child(3) { top: 11px; left: 0; height: 2px; width: 7px; }
  #hitmarker i:nth-child(4) { top: 11px; right: 0; height: 2px; width: 7px; }
  #channel-wrap { position: fixed; left: 50%; bottom: 21%; transform: translateX(-50%); width: 300px; display: none; text-align: center; }
